import{_ as t,o as a,c as o,ah as i}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Free signup and full-feature demo","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/admission/ecoles/inscription-et-demo.md","filePath":"src/en/admission/ecoles/inscription-et-demo.md"}'),n={name:"en/admission/ecoles/inscription-et-demo.md"};function s(r,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="free-signup-and-full-feature-demo" tabindex="-1">Free signup and full-feature demo <a class="header-anchor" href="#free-signup-and-full-feature-demo" aria-label="Permalink to &quot;Free signup and full-feature demo&quot;">​</a></h1><p>Discovering ERA requires no installation and no commitment: your school can create its own online space in a few minutes, free for a year, renewable, then switch to a full-feature demo to evaluate the whole solution before choosing a license.</p><h2 id="creating-your-school-s-account" tabindex="-1">Creating your school&#39;s account <a class="header-anchor" href="#creating-your-school-s-account" aria-label="Permalink to &quot;Creating your school&#39;s account&quot;">​</a></h2><p>Signup happens on Era Admission&#39;s public site: click <strong>Create my free space</strong> on its home page, then fill in a very short form:</p><ol><li>Your school&#39;s name.</li><li>Your name.</li><li>An email address.</li><li>A password.</li></ol><p>Submitting it creates <strong>nothing yet</strong>: an email goes out to the address you just typed, with a link to follow. That link, and only that link, opens your school&#39;s space. This step is what keeps a mistyped address from costing you your own space — your email address is, after all, the only way back in if you forget your password.</p><p>The link stays valid for two days. If nothing arrives, check your spam folder, then fill the form in again: the latest link replaces the previous one. An expired or already-used link simply returns you to the form, which says so.</p><p>Once the link is followed, two things are created automatically:</p><ul><li><strong>A dedicated space for your school</strong>, reachable at its own address (a subdomain built from your school&#39;s name, e.g. <code>college-sainte-marie.&lt;era-domain&gt;</code>).</li><li><strong>Your administrator account</strong>, with the email address and password you chose — this is the account that then manages everything else (users, structure, admissions...).</li></ul><p>A confirmation page reminds you of your space&#39;s address and lets you log in right away. That address is also emailed to you: keep that message. It&#39;s the one your team will use day to day, and it is where — and only where — a forgotten password is reset.</p><p>There is no account other than yours, and no password is sent to you: you log in with the email address and password you chose on the form.</p><h2 id="what-the-free-tier-covers" tabindex="-1">What the free tier covers <a class="header-anchor" href="#what-the-free-tier-covers" aria-label="Permalink to &quot;What the free tier covers&quot;">​</a></h2><p>The free tier isn&#39;t a limited version of all of ERA: it&#39;s a single module, built so you can get started right away —</p><ul><li>the <strong>public application form</strong>, which families can already use from day one to submit an application;</li><li>the <strong>read-only application queue</strong>, to keep track of what comes in.</li></ul><p>The rest of the application (academic life, finances, family relations, the reporting dashboard...) isn&#39;t accessible on this tier. If you want to see the application as a whole before committing, that&#39;s what the full-feature demo below is for.</p><h2 id="activating-the-full-feature-demo" tabindex="-1">Activating the full-feature demo <a class="header-anchor" href="#activating-the-full-feature-demo" aria-label="Permalink to &quot;Activating the full-feature demo&quot;">​</a></h2><p>Once logged into your space on the free tier, your administrator account sees an invitation on its dashboard to activate a full-feature demo: it temporarily unlocks every ERA module, with no commitment, so you can evaluate the solution under real conditions before choosing a license.</p><p>Activation itself — and how the demo winds down (duration, the &quot;expiring soon&quot; banner, the return to the free tier) — is covered from the administrator&#39;s point of view in <a href="/era-guide/en/guide/admin/demo-et-journal.html">Full-feature demo and activity log</a>; this guide doesn&#39;t duplicate that content.</p><p>In short, what matters before you decide:</p><ul><li>The demo runs for a fixed number of days from activation.</li><li>It can only be activated once, from the free tier — you can&#39;t restart it indefinitely on your own.</li><li>Once active, it can only be ended early by the edPage team (see <a href="/era-guide/en/admission/staff-edpage/">the internal edPage panel</a>), not from your dashboard.</li></ul><h2 id="what-happens-when-the-demo-ends" tabindex="-1">What happens when the demo ends <a class="header-anchor" href="#what-happens-when-the-demo-ends" aria-label="Permalink to &quot;What happens when the demo ends&quot;">​</a></h2><p>You don&#39;t have to watch the calendar: a week before the deadline, an email warns the school&#39;s administrator accounts, with the exact date. A second message goes out on the day the demo ends.</p><p>If no license has been purchased by the time the demo period ends, your space <strong>automatically returns to the free ERA Admissions tier</strong>: the public application form and the application queue keep working, and the other modules lock again. It&#39;s the same state a demo manually ended by the edPage team reaches.</p><p><strong>Nothing is deleted.</strong> What you entered during the demo (classes, students, grades, payments...) is kept, only hidden while the modules are locked. It comes back as it was the day you take a license: no re-entry.</p><p>The demo can&#39;t be started a second time. To get the whole of ERA back, see <a href="/era-guide/en/admission/ecoles/passage-licence.html">Moving to a license</a> as soon as you&#39;re ready to commit.</p>',25)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
